from abc import ABC, abstractmethod


class Yetkazish(ABC):
    @abstractmethod
    def narx(self, ogirlik):
        pass


class Oddiy(Yetkazish):
    def narx(self, ogirlik):
        return 1000 + 50 * ogirlik


class Tez(Yetkazish):
    def narx(self, ogirlik):
        return 3000 + 120 * ogirlik


class Bepul(Yetkazish):
    def narx(self, ogirlik):
        return 0


def yarat(tur):
    if tur == "tez":
        return Tez()
    if tur == "bepul":
        return Bepul()
    return Oddiy()


yetkazish = yarat(input())
n = int(input())
for ogirlik in map(int, input().split()):
    print(yetkazish.narx(ogirlik))

