import java.util.Scanner;

public class Main {
    interface Yetkazish {
        long narx(long ogirlik);
    }

    static class Oddiy implements Yetkazish {
        public long narx(long ogirlik) { return 1000 + 50 * ogirlik; }
    }

    static class Tez implements Yetkazish {
        public long narx(long ogirlik) { return 3000 + 120 * ogirlik; }
    }

    static class Bepul implements Yetkazish {
        public long narx(long ogirlik) { return 0; }
    }

    static Yetkazish yarat(String tur) {
        if (tur.equals("tez")) return new Tez();
        if (tur.equals("bepul")) return new Bepul();
        return new Oddiy();
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        Yetkazish yetkazish = yarat(in.next());
        int n = in.nextInt();
        for (int i = 0; i < n; i++) {
            System.out.println(yetkazish.narx(in.nextLong()));
        }
    }
}

