#include <iostream>
#include <memory>
#include <string>
using namespace std;

class Yetkazish {
public:
    virtual ~Yetkazish() = default;
    virtual long long narx(long long ogirlik) const = 0;
};

class Oddiy : public Yetkazish {
public:
    long long narx(long long ogirlik) const override { return 1000 + 50 * ogirlik; }
};

class Tez : public Yetkazish {
public:
    long long narx(long long ogirlik) const override { return 3000 + 120 * ogirlik; }
};

class Bepul : public Yetkazish {
public:
    long long narx(long long) const override { return 0; }
};

int main() {
    string tur;
    cin >> tur;
    unique_ptr<Yetkazish> yetkazish;
    if (tur == "tez")
        yetkazish = make_unique<Tez>();
    else if (tur == "bepul")
        yetkazish = make_unique<Bepul>();
    else
        yetkazish = make_unique<Oddiy>();
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) {
        long long ogirlik;
        cin >> ogirlik;
        cout << yetkazish->narx(ogirlik) << endl;
    }
    return 0;
}
